-- Supabase SQL Editor ga tashlab ishga tushiriladi (MCP orqali ham qo'llanadi)
create table if not exists public.zk_firmalar (
  id bigint generated by default as identity primary key,
  nomi text not null, turi text not null check (turi in ('pechat','qogoz')),
  faol boolean not null default true, unique (nomi, turi));
create table if not exists public.zk_sozlamalar (kalit text primary key, qiymat text not null);
create table if not exists public.zk_zakazlar (
  id bigint primary key, berilgan date not null default current_date, srok date,
  mijoz text not null default '', dona integer not null default 0, chiqish numeric not null default 1,
  fayl_nomi text not null default '', format_h numeric, format_i numeric, gramm numeric,
  zapas integer not null default 100, list_soni integer, rulon_kg numeric, qogoz_summa numeric,
  laminatsiya_kerak boolean not null default false, laminatsiya_tayyor boolean not null default false, laminatsiya_summa numeric,
  lak_kerak boolean not null default false, lak_turi text not null default '', lak_tayyor boolean not null default false, lak_summa numeric,
  fayl_tayyor boolean not null default false, ctp_tayyor boolean not null default false, noj_tayyor boolean not null default false,
  pechat_firma text not null default '', pechat_tayyor boolean not null default false,
  qogoz_firma text not null default '', qogoz_holat text not null default 'yoq' check (qogoz_holat in ('yoq','buyurtma','olindi')),
  qora_turi text not null default 'micro' check (qora_turi in ('yoq','micro','macro','5sloy')), qora_gramm numeric, qora_h numeric, qora_i numeric,
  holat text not null default 'jarayonda' check (holat in ('jarayonda','bitdi','otmen')), izoh text not null default '',
  created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists zk_zakazlar_holat_idx on public.zk_zakazlar (holat, srok);
create or replace function public.zk_touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
drop trigger if exists zk_zakazlar_touch on public.zk_zakazlar;
create trigger zk_zakazlar_touch before update on public.zk_zakazlar for each row execute function public.zk_touch_updated_at();
create or replace function public.zk_keyingi_raqam() returns bigint language sql stable as $$ select coalesce(max(id),0)+1 from public.zk_zakazlar $$;
alter table public.zk_zakazlar enable row level security; alter table public.zk_firmalar enable row level security; alter table public.zk_sozlamalar enable row level security;
create policy "zk_auth_all" on public.zk_zakazlar for all to authenticated using (true) with check (true);
create policy "zk_firma_auth_all" on public.zk_firmalar for all to authenticated using (true) with check (true);
create policy "zk_soz_auth_all" on public.zk_sozlamalar for all to authenticated using (true) with check (true);
insert into public.zk_firmalar (nomi, turi) values ('Print Well A1','pechat'),('Print Well A2','pechat'),('Mesniy','pechat'),('Izzatilla Print','pechat'),('Poytaxt A0','pechat'),('Pechatsiz','pechat'),('Poytaxt','qogoz'),('Mars Paper','qogoz'),('Mesniy','qogoz'),('Emil','qogoz') on conflict do nothing;
insert into public.zk_sozlamalar (kalit, qiymat) values ('zapas_default','100'),('gramm_micro','310'),('gramm_macro','375'),('gramm_5sloy','620'),('srok_kun','10') on conflict do nothing;
